<?php require_once __DIR__.'/../config/config.php';$s=db()->prepare("SELECT * FROM waste_types WHERE company_id=? ORDER BY name");$s->execute([current_company_id()]);$rows=$s->fetchAll();$active='report_stock';$title='Stok Sampah';require __DIR__.'/../includes/header.php';?><div class="section-head"><div><h1>Laporan Stok Sampah</h1><p class="muted">Daftar jenis sampah beserta stok, harga beli, dan harga jual.</p></div><div><a class="btn ghost sm" href="../index.php">← Kembali</a></div></div><div class="table-wrap"><table class="table"><tr><th>Jenis</th><th>Satuan</th><th class="right">Stok</th><th class="right">Harga Beli</th><th class="right">Harga Jual</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['unit'])?></td><td class="right"><?=number_format((float)$r['stock_kg'],2,',','.')?> kg</td><td class="right"><?=rupiah((float)$r['buy_price'])?></td><td class="right"><?=rupiah((float)$r['sell_price'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../includes/footer.php';?>